// Подписи параметров для сообщения о сборе и настроек, в порядке показа. Технические (items_on_page,
// enable_snippets, ored_clusters) не показываем
const SEARCH_LABELS = {
  work_format: { REMOTE: 'удалёнка' },
  professional_role: { 96: 'программист, разработчик' },
  education: { not_required_or_not_specified: 'образование не важно' },
  search_period: { 1: 'за сутки', 3: 'за 3 дня', 7: 'за неделю' },
  order_by: { publication_time: 'сначала новые' },
};

// Ссылка на ту же выдачу на hh (page — с нуля, как в запросе)
const searchUrl = (page, s) =>
  `${SEARCH_URL}?${[...searchQuery(s), ['page', String(page)]]
    .map(([key, value]) => `${key}=${encodeURIComponent(value)}`)
    .join('&')}`;

// Что искали, по-человечески: где какие слова и строка фильтров
function describeSearch(s) {
  const query = searchQuery(s);
  const filters = Object.keys(SEARCH_LABELS).flatMap((key) =>
    query.filter(([name]) => name === key).map(([, value]) => SEARCH_LABELS[key][value] ?? `${key}=${value}`),
  );
  return {
    words: `везде в тексте: ${s['search.anywhere'].join(' · ')}\nв названии: ${s['search.in_name'].join(' · ')}`,
    filters: filters.join(' · '),
  };
}
// Расписание сбора W1 по Москве (UTC+3, без перехода на летнее время). С 07.10.2026 задаётся в боте
// (⚙️ Настройки → 🕐 Сбор, n8n/shared/settings.js → scheduleFrom), сбор запускают «часы» W8 Clock.
// sch = { dayFrom, dayTo, dayEvery, nightEvery, paused }: днём [dayFrom, dayTo) — каждые dayEvery мин, ночью — каждые
// nightEvery мин (0 — ночью не собирать). Слоты выровнены по полуночи МСК, шаг сетки — 15 мин.
// По умолчанию (решение пользователя 07.10.2026) — 29 сборов в сутки: днём 07:00–17:30 каждые 30 мин,
// ночью 18, 20, 22, 00, 02, 04, 06.
// Общий код W1 «Score job», W6 «Summary», W7 «Render», W8 «Due»: строка «// @include n8n/shared/schedule.js».

const COLLECT_STEP = 15 * 60 * 1000;
const DEFAULT_SCHEDULE = { dayFrom: 7, dayTo: 18, dayEvery: 30, nightEvery: 120, paused: false };

// Момент t (мс, кратен 15 мин) — сбор по расписанию?
function isCollectSlot(t, sch = DEFAULT_SCHEDULE) {
  if (sch.paused) return false;
  const msk = new Date(t + 3 * 3600 * 1000);
  const hour = msk.getUTCHours();
  const every = hour >= sch.dayFrom && hour < sch.dayTo ? sch.dayEvery : sch.nightEvery;
  return every > 0 && (hour * 60 + msk.getUTCMinutes()) % every === 0;
}

// Сколько сборов по расписанию в промежутке (from, to]
function countCollectSlots(from, to, sch = DEFAULT_SCHEDULE) {
  let n = 0;
  for (let t = Math.floor(from / COLLECT_STEP) * COLLECT_STEP + COLLECT_STEP; t <= to; t += COLLECT_STEP) {
    if (isCollectSlot(t, sch)) n++;
  }
  return n;
}

// Ближайший сбор по расписанию после момента t; null — на паузе
function nextCollect(t, sch = DEFAULT_SCHEDULE) {
  if (sch.paused) return null;
  let s = Math.floor(t / COLLECT_STEP) * COLLECT_STEP + COLLECT_STEP;
  for (let i = 0; i < 2 * 96; i++, s += COLLECT_STEP) if (isCollectSlot(s, sch)) return s;
  return null;
}

// Сборов в сутки по расписанию
const collectsPerDay = (sch = DEFAULT_SCHEDULE) => countCollectSlots(0, 24 * 3600 * 1000, { ...sch, paused: false });

// Расписание словами: «днём 07–18 МСК каждые 30 мин, ночью каждые 2 ч»
function describeSchedule(sch = DEFAULT_SCHEDULE) {
  const every = (m) => (m % 60 ? `${m} мин` : `${m / 60} ч`);
  const pad = (n) => String(n).padStart(2, '0');
  const night = sch.nightEvery > 0 ? `ночью каждые ${every(sch.nightEvery)}` : 'ночью не собирать';
  return `днём ${pad(sch.dayFrom)}–${pad(sch.dayTo)} МСК каждые ${every(sch.dayEvery)}, ${night}`;
}

// Расписание стража healthchecks.io: OnCalendar (строка дня и строка ночи) и запас (grace, с)
function onCalendar(sch = DEFAULT_SCHEDULE) {
  const pad = (n) => String(n).padStart(2, '0');
  const minutes = [];
  for (let m = 0; m < 60; m += Math.min(sch.dayEvery, 60)) minutes.push(pad(m));
  const lines = [`${pad(sch.dayFrom)}..${pad(sch.dayTo - 1)}:${minutes.join(',')} Europe/Moscow`];
  if (sch.nightEvery > 0) {
    const hours = [];
    for (let h = 0; h < 24; h++) {
      if ((h < sch.dayFrom || h >= sch.dayTo) && (h * 60) % sch.nightEvery === 0) hours.push(pad(h));
    }
    if (hours.length) lines.push(`${hours.join(',')}:00 Europe/Moscow`);
  }
  return { schedule: lines.join('\n'), grace: (sch.dayEvery + 20) * 60 };
}
// Общий код робота-отклика (этап 6, docs/stages/stage-6.md): W3, W5, W6, W7, W9.
// Подключается строкой «// @include n8n/shared/robot.js» после n8n/shared/card.js (нужны esc и thaiDate).

const VNC_URL = 'vnc://localhost:5901';
const DAY_MS = 24 * 3600 * 1000;

// Можно ли откликнуться роботом: ✅ с письмом, без теста работодателя и не на сайте работодателя, не в очереди.
// enabled — настройка apply.enabled (W3 её не читает: выключенного робота поймает W9 при нажатии)
const robotEligible = (r, enabled = true) =>
  Boolean(enabled && r?.status === 'approved' && r.letter && !r.has_test && r.apply_type !== 'external' && !r.apply_state);

// «День» робота для лимита — с 09:00 по Таиланду (02:00 UTC), решение пользователя 10.10.2026
function robotDayStart(now = Date.now()) {
  const d = new Date(now);
  const start = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), 2);
  return start > now ? start - DAY_MS : start;
}
// Живые отклики робота за текущий «день»
const robotToday = (rows, now = Date.now()) =>
  rows.filter((r) => r.apply_by === 'robot' && Date.parse(r.applied_at) >= robotDayStart(now)).length;

// Тихие часы 23:00–09:00 по Таиланду (UTC+7)
function quietHours(now = Date.now()) {
  const h = new Date(now + 7 * 3600 * 1000).getUTCHours();
  return h >= 23 || h < 9;
}

// Время по Таиланду: '2026-10-11T07:32:00Z' → '14:32'
const thaiTime = (iso) =>
  Date.parse(iso) ? new Date(Date.parse(iso) + 7 * 3600 * 1000).toISOString().slice(11, 16) : '';

// Как ушло письмо — в строку «🚀 Отправлено»
const LETTER_HOW = { attached: ' · ✉️ письмо приложено', chat: ' · 💬 письмо — в чате отклика', none: ' · ⚠️ без письма' };

// Строка робота в сообщении с письмом: очередь, итог, пометка. r — строка вакансии
// (+ robot_wait — чего ждёт робот: «капчу hh», «вход в hh»…)
function robotLine(r) {
  if (r.apply_state === 'queued' || r.apply_state === 'applying') {
    return r.robot_wait ? `⏸ Робот ждёт: ${esc(r.robot_wait)}` : '⏳ Робот откликается…';
  }
  if (r.status === 'applied' && r.apply_by === 'robot') {
    return `🚀 Отправлено ${thaiDate(r.applied_at)} ${thaiTime(r.applied_at)}${LETTER_HOW[r.apply_letter] ?? ''}${
      r.apply_note ? `\n⚠️ hh: ${esc(r.apply_note)}` : ''
    }`;
  }
  if (r.status === 'applied' && r.apply_by === 'hh') return '📨 Отклик уже был на hh — отметил';
  if (r.status !== 'approved') return '';
  const note = r.apply_note ? `: ${esc(r.apply_note)}` : '';
  const lines = {
    test: '🧩 У вакансии вопросы работодателя — откликнитесь сами',
    external: '🌐 Отклик на сайте работодателя — откликнитесь сами',
    hidden: '🙈 hh просит открыть резюме этому работодателю — откликнитесь сами',
    error: `⚠️ Робот не смог${note}${(r.apply_tries ?? 0) >= 3 ? ' — третий раз, откликнитесь сами' : ''}`,
    dry_run: `🧪 Сухой прогон (APPLY_LIVE=0), отклик не отправлен${note}`,
    disabled: '⏸ Робот выключен (⚙️ → 🚀 Робот) — откликнитесь сами',
  };
  return lines[r.apply_result] ?? '';
}

const job = $('Job').first().json;
const rows = $('Rows')
  .all()
  .map((i) => i.json)
  .filter((r) => r.id);
// Журнал сборов — по имени ноды: перед «Render» может стоять «Robot health» (⚙️ → 🚀 Робот)
const runs = $('Runs')
  .all()
  .map((i) => i.json)
  .filter((r) => r.id)
  .sort((a, b) => Date.parse(b.started_at) - Date.parse(a.started_at));
const state = $getWorkflowStaticData('global');
const panel = state.panel ?? {};

const now = Date.now();
const DAY = 24 * 3600 * 1000;
const PAGE = 8;
// Порядок = PANEL_LAYOUTS в scripts/build-workflows.mjs (выходы «Layout»); после них — приветствие
const LAYOUTS = [
  'list',
  'open_choose',
  'open_decided',
  'open_plain',
  'stats',
  'settings',
  'set_collect',
  'set_search',
  'set_filter',
  'set_rules',
  'set_blacklist',
  'set_confirm',
  'set_llm',
  'open_rescue',
  'set_apply',
];
// Выходы «Layout» после раскладок: приветствие, вопрос ⚙️ со списком (ForceReply)
const ROUTE_START = LAYOUTS.length * 2;
const ROUTE_PROMPT = LAYOUTS.length * 2 + 1;
const chatId = String(job.chatId || $env.TG_CHAT_ID);
// sync — после «📨 Отправил» / «↩️ Отменить» под письмом (W3 «Sync job»): перерисовать панель,
// только если на ней открыта эта вакансия — иначе на ней нечего обновлять
if (job.view === 'sync' && !(panel.view === 'open' && Number(panel.id) === Number(job.id) && panel.messageId)) {
  return [];
}
// Кнопка в панели, перерисовка после решения, sync — правим панель; кнопка меню, /v…, «📋 К вакансиям» — новая.
// Ответ на вопрос ⚙️ со списком — правим панель, на которой нажали «✏️»
const target = job.view === 'sync' || job.input ? panel.messageId : job.messageId;
const edit = Boolean(target);
const at = (s) => Date.parse(s) || 0;
const count = (list, f) => list.filter(f).length;
const pct = (a, b) => (b ? Math.round((a / b) * 100) : 0);

// Время: по Таиланду (UTC+7), в скобках — по Москве (UTC+3)
const hhmm = (t, offset) => new Date(t + offset * 3600 * 1000).toISOString().slice(11, 16);
const thaiMsk = (t) => `${hhmm(t, 7)} (${hhmm(t, 3)} МСК)`;
function span(ms) {
  const m = Math.max(0, Math.round(ms / 60000));
  if (m < 1) return 'меньше минуты';
  if (m < 60) return `${m} мин`;
  const h = Math.floor(m / 60);
  if (h < 24) return h < 3 && m % 60 ? `${h} ч ${m % 60} мин` : `${h} ч`;
  return `${Math.floor(h / 24)} д`;
}

// ---------- Список ----------

const inTab = (key) => {
  const statuses = TABS[key].statuses;
  return rows.filter((r) => (statuses ? statuses.includes(r.status) : r.status !== 'seen'));
};
const counts = Object.fromEntries(Object.keys(TABS).map((key) => [key, inTab(key).length]));

function itemLines(r, n) {
  const icons = `${VERDICT_ICON[r.decision] ?? ''}${statusIcon(r)}`;
  const age = now - at(r.createdAt);
  const meta = [
    esc(r.company),
    r.status === 'rejected' ? `🚫 ${esc(String(r.reasons ?? '').split(', ')[0].replace(/:.*$/, ''))}` : salary(r),
    r.status === 'applied' && r.applied_at
      ? `${r.apply_by === 'robot' ? '🚀' : '📨'} ${thaiDate(r.applied_at)}`
      : r.my_decision === 'earlier'
        ? '📨 раньше'
      : age < DAY
        ? `${span(age)} назад`
        : thaiDate(r.createdAt),
    `/v${r.id}`,
  ]
    .filter(Boolean)
    .join(' · ');
  return `${n}. ${icons} <a href="${r.url}">${esc(r.title)}</a>\n   ${meta}`;
}

function listView(tabKey, pageNo, note = '') {
  const tab = TABS[tabKey] ? tabKey : counts.wait ? 'wait' : 'all';
  const items = inTab(tab).sort((a, b) => (tab === 'sent' ? at(b.applied_at) - at(a.applied_at) : 0) || b.id - a.id);
  const pages = Math.max(1, Math.ceil(items.length / PAGE));
  const page = Math.min(Math.max(1, Number(pageNo) || 1), pages);
  const lines = items.slice((page - 1) * PAGE, page * PAGE).map((r, i) => itemLines(r, (page - 1) * PAGE + i + 1));
  const { icon, name } = TABS[tab];
  const head = `📋 <b>Вакансии</b> · ${icon} ${name} — ${items.length}${pages > 1 ? ` · стр. ${page}/${pages}` : ''}`;
  const off = { text: '·', cb: 'p:x' };
  return {
    layout: 'list',
    tab,
    page,
    text: `${[note, head].filter(Boolean).join('\n')}\n\n${lines.length ? lines.join('\n') : 'Здесь пока пусто.'}`,
    b: {
      tabs: Object.keys(TABS).map((key) => ({
        text: `${key === tab ? '• ' : ''}${TABS[key].icon} ${counts[key]}`,
        cb: `p:l:${key}:1`,
      })),
      prev: page > 1 ? { text: '◀️', cb: `p:l:${tab}:${page - 1}` } : off,
      // Номер страницы — обновить её (новые вакансии, решения)
      mid: { text: `${page}/${pages}`, cb: `p:l:${tab}:${page}` },
      next: page < pages ? { text: '▶️', cb: `p:l:${tab}:${page + 1}` } : off,
    },
  };
}

// ---------- Карточка на панели ----------

function openView(id) {
  // Вкладка для «⬅️ К списку»: из кнопки панели (pv:…), а для /v… — та, что сейчас открыта на панели
  const fromJob = Boolean(TABS[job.tab]);
  const tab = fromJob ? job.tab : TABS[panel.tab] ? panel.tab : 'all';
  const page = Number(fromJob ? job.page : panel.page) || 1;
  const r = rows.find((x) => x.id === id);
  if (!r) return listView(tab, page, `⚠️ Вакансии /v${id} нет в базе`);

  const extra = [
    ['new', 'detailed'].includes(r.status) && '⚙️ Ждёт оценки нейросетью',
    r.status === 'seen' && '🗄 Из первой выгрузки — не оценивалась',
    r.letter && r.status === 'approved' && !r.apply_state && '✉️ Письмо готово — в ленте под карточкой',
    // Робот-отклик (этап 6): очередь, пометка об исходе
    robotLine(r),
  ].filter(Boolean);
  // Строка «🤖 …» пустая, если нейросеть вакансию не оценивала (отсеяна фильтром, бэкфилл)
  const card = cardText(r)
    .split('\n')
    .filter((line) => line !== '🤖 ')
    .join('\n');

  // Кнопки решения — только если есть исходная карточка в ленте: решение правит и её (W3, callback pv:…)
  let layout = 'open_plain';
  // Отсеянная фильтром (08.10.2026): решение без карточки в ленте — W3 отправит её сам, или «🤖 На оценку»
  if (r.status === 'rejected') layout = 'open_rescue';
  else if (r.tg_message_id && (r.status === 'waiting' || job.choose)) layout = 'open_choose';
  // «📨 Откликался раньше» тоже можно отменить «↩️ Изменить» (отклик через бота — только «↩️ Отменить» под письмом)
  else if (
    r.tg_message_id &&
    (['approved', 'maybe', 'skipped'].includes(r.status) || (r.status === 'applied' && r.my_decision === 'earlier'))
  ) {
    layout = 'open_decided';
  }

  const choice = (c) => `pv:${r.id}:${c}:${tab}:${page}`;
  return {
    layout,
    tab,
    page,
    text: [`🔎 <b>Вакансия</b> /v${r.id}`, '', card, ...extra].join('\n'),
    b: {
      apply: choice('apply'),
      maybe: choice('maybe'),
      skip: choice('skip'),
      earlier: choice('earlier'),
      ban: choice('ban'),
      edit: choice('edit'),
      score: choice('score'),
      url: r.url,
      back: `p:l:${tab}:${page}`,
    },
  };
}

// ---------- Статистика ----------

function statsView() {
  // Журнал сборов runs (W1 «Start run» / «Finish run»), свежие сверху
  const last = runs[0];
  const next = nextCollect(now, collectSchedule);

  // За сутки — как в утренней сводке W6: окно до «сейчас − 10 мин», только сборы по расписанию
  const windowEnd = now - 10 * 60 * 1000;
  const windowStart = windowEnd - DAY;
  const expected = countCollectSlots(windowStart, windowEnd, collectSchedule);
  const collected = count(
    runs,
    (r) =>
      ['schedule', 'catchup'].includes(r.kind) &&
      r.status === 'ok' &&
      at(r.started_at) > windowStart &&
      at(r.started_at) <= windowEnd,
  );

  let lastLine = '• последний: сборов ещё не было';
  if (last) {
    const started = at(last.started_at);
    // running дольше 10 мин — сбор упал, не дойдя до «Finish run» (ошибка ушла в W4)
    const stale = last.status === 'running' && now - started > 10 * 60 * 1000;
    const error = String(last.error ?? '');
    const result =
      last.status === 'ok'
        ? `✅ новых ${last.fresh ?? 0}${last.cards ? `, карточек ${last.cards}` : ''}`
        : last.status === 'error'
          ? `⚠️ ошибка${error ? `: ${esc(error.length > 80 ? `${error.slice(0, 79)}…` : error)}` : ''}`
          : stale
            ? '⚠️ не завершился'
            : '⏳ идёт';
    lastLine = `• последний: ${thaiMsk(started)}, ${span(now - started)} назад — ${result}`;
  }

  const found = rows.filter((r) => r.status !== 'seen');
  const scored = rows.filter((r) => ['apply', 'maybe', 'skip', 'error'].includes(r.decision));
  const cards = rows.filter((r) => r.tg_message_id);
  const reviewed = count(cards, (r) => r.my_decision);
  const waiting = rows.filter((r) => r.status === 'waiting');
  const oldest = Math.min(...waiting.map((r) => at(r.card_at || r.createdAt)));
  const status = (s) => count(rows, (r) => r.status === s);
  // Теневой режим — только решения apply / maybe / skip («📨 откликался раньше» не сравниваем)
  const DECISIONS = ['apply', 'maybe', 'skip'];
  const shadow = rows.filter((r) => DECISIONS.includes(r.my_decision) && DECISIONS.includes(r.decision));
  const earlier = count(rows, (r) => r.status === 'applied' && r.my_decision === 'earlier');
  const agree = count(shadow, (r) => r.my_decision === r.decision);
  const errors = count(scored, (r) => r.decision === 'error');

  const lines = [
    `📊 <b>Статистика</b> · ${hhmm(now, 7)} по Таиланду`,
    '',
    `🔎 <b>Сбор</b> · ${describeSchedule(collectSchedule)}`,
    lastLine,
    next ? `• следующий: ${thaiMsk(next)}, через ${span(next - now)}` : '• ⏸ сбор на паузе (⚙️ Настройки → 🕐 Сбор)',
    `• за сутки: ${collected} из ${expected} по расписанию`,
    '',
    `📥 <b>Вакансии</b>: найдено ${found.length}, за сутки +${count(found, (r) => at(r.createdAt) >= now - DAY)}`,
    `• 🚫 отсеяно фильтром: ${status('rejected')} · ⚙️ ждут нейросети: ${status('new') + status('detailed') + status('scoring')}`,
    `• 🤖 оценено ${scored.length}: 🟢 ${count(scored, (r) => r.decision === 'apply')} · 🟡 ${count(scored, (r) => r.decision === 'maybe')} · 🔴 ${count(scored, (r) => r.decision === 'skip')}${errors ? ` · ⚠️ ${errors}` : ''}`,
    '',
    `👤 <b>Рассмотрено тобой</b>: ${reviewed} из ${cards.length} (${pct(reviewed, cards.length)}%)`,
    `• ⏳ ждут решения: ${waiting.length}${waiting.length ? `, старейшая — ${span(now - oldest)}` : ''}`,
    `• ✅ ${status('approved')} · 🤔 ${status('maybe')} · ❌ ${status('skipped')} · 📨 отправлено ${status('applied') - earlier}${earlier ? ` · 📨 раньше ${earlier}` : ''}`,
    `• ⌛ устарели ${status('expired')} · 🔒 закрылись ${status('archived')}`,
    '',
    `🧪 Теневой режим: ${shadow.length}/50${shadow.length ? `, совпало ${agree} (${pct(agree, shadow.length)}%)` : ''}`,
  ];
  // Робот-отклик (этап 6): сегодня — с 09:00 по Таиланду
  const robotSent = rows.filter((r) => r.status === 'applied' && r.apply_by === 'robot');
  if (robotSent.length || rows.some((r) => r.apply_state)) {
    lines.push(
      '',
      `🚀 <b>Робот</b>: сегодня ${robotToday(rows, now)}/${settings['apply.daily_limit']} · в очереди ${count(rows, (r) => r.apply_state)} · всего ${robotSent.length} (✉️ ${count(robotSent, (r) => r.apply_letter === 'attached')} · 💬 ${count(robotSent, (r) => r.apply_letter === 'chat')})`,
    );
  }
  return {
    layout: 'stats',
    tab: panel.tab,
    page: panel.page,
    text: lines.filter((line, i) => line !== '' || lines[i - 1] !== '').join('\n'),
    b: { wait: { text: `⏳ Ждут решения · ${counts.wait}`, cb: 'p:l:wait:1' } },
  };
}

// W7 · Render — раздел «⚙️ Настройки» панели меню (07.10.2026). Подключается в render.js строкой
// «// @include n8n/w7-menu/settings-view.js», после помощников времени (thaiMsk, hhmm).
// Значения — из таблицы settings плюс изменение этого нажатия: «Setting change» выполнилась раньше (ветка выше).
// Раскладки: settings (корень), set_collect, set_search, set_filter, set_rules, set_blacklist, set_confirm, set_llm,
// set_apply (🚀 Робот, этап 6: состояние робота — «Robot health», GET /health робота).
// Кнопки «▸» — следующее значение по кругу, «✏️» — вопрос со списком (ответ — сообщением).

const ranNode = (name) => {
  try {
    return $(name)
      .all()
      .map((i) => i.json);
  } catch {
    return []; // нода в этом запуске не выполнялась
  }
};
const settingChange = ranNode('Setting change')[0];
const settings = {
  ...loadSettings($('Settings').all()),
  ...(settingChange ? { [settingChange.name]: settingChange.value } : {}),
};
const collectSchedule = scheduleFrom(settings);
// Чёрный список: строки таблицы blacklist, без только что убранной («Delete ban» выполнилась раньше)
const unbanned = Number(job.unban) || 0;
const blacklist = ranNode('Blacklist').filter((r) => r.id && r.id !== unbanned);

const everyText = (m) => (m % 60 ? `${m} мин` : `${m / 60} ч`);
const pad2 = (n) => String(n).padStart(2, '0');
const periodText = (days) => SEARCH_LABELS.search_period[days] ?? `за ${days} дн.`;
const responsesText = (n) => (n ? `больше ${n}` : 'не отсекать');
const VERDICT_TEXT = { apply: '🟢 apply', maybe: '🟡 maybe', skip: '🔴 skip' };
const providerText = (p) => (p === 'claude' ? 'Claude' : 'Gemini');
const rulesOn = () => Object.keys(FILTER_RULES).filter((id) => !settings['filter.rules_off'].includes(id));
const companies = (n) => {
  const d = n % 10;
  const dd = n % 100;
  if (d === 1 && dd !== 11) return `${n} компания`;
  return d >= 2 && d <= 4 && (dd < 12 || dd > 14) ? `${n} компании` : `${n} компаний`;
};

// Что сделало это нажатие: «✅ Записал», ошибка ввода списка
function changeNotes() {
  const notes = [];
  if (settingChange) notes.push('✅ Записал');
  if (job.input && !settingChange) {
    const parsed = SETTINGS[job.input.name]?.cases ? parseCases(job.input.text) : parseWords(job.input.text);
    if (parsed.error) notes.push(`⚠️ Не записал: ${esc(parsed.error)}. Нажми ✏️ и пришли список ещё раз`);
  }
  return notes;
}

function settingsRootView(note) {
  const sch = collectSchedule;
  const lines = [
    '⚙️ <b>Настройки</b>',
    '',
    `🕐 <b>Сбор</b>: ${describeSchedule(sch)} · ${collectsPerDay(sch)} в сутки${sch.paused ? ' · ⏸ <b>пауза</b>' : ''}`,
    `🔎 <b>Поиск</b>: ${periodText(settings['search.period'])} · везде — ${settings['search.anywhere'].length} сл., в названии — ${settings['search.in_name'].length}`,
    `🧹 <b>Фильтр</b>: правил ${rulesOn().length} из ${Object.keys(FILTER_RULES).length} · отклики — ${responsesText(settings['filter.max_responses'])} · стоп-слов ${settings['filter.stop_words'].length} · ЧС ${blacklist.length}`,
    `🤖 <b>Нейросеть</b>: ${providerText(settings['llm.provider'])} · теневой режим ${settings['llm.shadow'] ? 'вкл' : 'выкл'} · спорных случаев ${settings['llm.cases'].length}`,
    `🚀 <b>Робот</b>: ${settings['apply.enabled'] ? 'вкл' : 'выкл'}${settings['apply.paused'] ? ' · ⏸ пауза' : ''} · сегодня ${robotToday(rows, now)}/${settings['apply.daily_limit']} · ${robotState().short}`,
  ];
  if (note) lines.push('', note);
  return {
    layout: 'settings',
    text: lines.join('\n'),
    b: {
      collect: { cb: 's:collect' },
      search: { cb: 's:search' },
      filter: { cb: 's:filter' },
      llm: { cb: 's:llm' },
      apply: { cb: 's:apply' },
    },
  };
}

function settingsCollectView() {
  const sch = collectSchedule;
  const next = nextCollect(now, sch);
  const lines = [
    '🕐 <b>Сбор</b>',
    '',
    `Днём — ${pad2(sch.dayFrom)}:00–${pad2(sch.dayTo)}:00 МСК (${pad2((sch.dayFrom + 4) % 24)}:00–${pad2((sch.dayTo + 4) % 24)}:00 у тебя): каждые ${everyText(sch.dayEvery)}`,
    `Ночью: ${sch.nightEvery ? `каждые ${everyText(sch.nightEvery)}` : 'не собирать'}`,
    sch.paused
      ? '⏸ <b>На паузе</b>: сборов нет. «▶️ Возобновить» — и сбор пойдёт по расписанию'
      : `Сборов в сутки: ${collectsPerDay(sch)} · следующий: ${next ? thaiMsk(next) : '—'}`,
  ];

  const notes = changeNotes();
  const hc = ranNode('HC sync')[0];
  if (hc) {
    const error = hc.error ? String(hc.error.message ?? hc.error) : '';
    if (!error) {
      notes.push(sch.paused ? '🛡 Страж healthchecks на паузе' : '🛡 Страж healthchecks: расписание обновлено');
    } else if (/credential/i.test(error)) {
      notes.push('⚠️ Страж healthchecks не обновлён: нет ключа API — HC_API_KEY в .env, потом деплой');
    } else {
      notes.push(`⚠️ Страж healthchecks не обновлён: ${esc(error.slice(0, 120))}`);
    }
  }
  if (job.collectNow) notes.push('🔄 Запустил сбор — итог придёт сообщением о сборе');
  if (notes.length) lines.push('', ...notes);

  return {
    layout: 'set_collect',
    text: lines.join('\n'),
    b: {
      day: { text: `Днём: ${everyText(sch.dayEvery)} ▸`, cb: 'sc:collect.day_every' },
      night: { text: `Ночью: ${sch.nightEvery ? everyText(sch.nightEvery) : 'выкл'} ▸`, cb: 'sc:collect.night_every' },
      window: { text: `День: ${pad2(sch.dayFrom)}–${pad2(sch.dayTo)} МСК ▸`, cb: 'sc:collect.day_window' },
      pause: { text: sch.paused ? '▶️ Возобновить' : '⏸ Пауза', cb: 'sc:collect.paused' },
    },
  };
}

function settingsSearchView() {
  const { words, filters } = describeSearch(settings);
  const lines = [
