}

// «✏️» в настройках — вопрос со списком отдельным сообщением; панель не трогаем
if (job.view === 'settings' && SETTING_PROMPTS[job.ask]) {
  return [
    {
      json: {
        route: ROUTE_PROMPT,
        view: 'prompt',
        layout: 'prompt',
        edit: false,
        chatId,
        messageId: 0,
